import 'package:freezed_annotation/freezed_annotation.dart';

part 'computer_move_ui.freezed.dart';

/// The move the computer has just played, as a screen reader says it: the
/// square it placed a die on, counting [row] and [col] from 0 at the top
/// left, and the [pips] that die shows once its capture, if any, is done.
///
/// Plain data generated by freezed (docs/adr/0011, docs/adr/0015).
@freezed
abstract class ComputerMoveUi with _$ComputerMoveUi {
  const factory ComputerMoveUi({
    required int row,
    required int col,
    required int pips,
  }) = _ComputerMoveUi;
}
